'use strict';
// Throwaway prototype. Balance and world-generation values are collected here.
const CFG={size:80,tile:32,vision:7,maxHP:60,moveDelay:110,enemyHP:30,enemyDamage:7,dice:3,relicXP:35,combatXP:15,levelXP:50,saveKey:'myworld-wilderlands-v1'};
const $=id=>document.getElementById(id), canvas=$('world'),ctx=canvas.getContext('2d');
const PALETTES={woodland:{grass:['#557644','#597b47','#527242','#5d7e49'],water:'#426b65',deep:'#355b59',sand:'#9a9462',tree:'#254d35',leaves:'#356044',highlight:'#527c4d',mountain:'#737b67',title:'Ashwood Expanse',sky:'#172c23'},autumn:{grass:['#8b824d','#928652','#847e48','#998957'],water:'#426967',deep:'#365657',sand:'#b6a36c',tree:'#60452e',leaves:'#a46e38',highlight:'#c18c48',mountain:'#89806b',title:'The Amber Wilds',sky:'#30291d'},frost:{grass:['#a0b8ac','#abc0b6','#96b0a4','#b0c4b9'],water:'#5b8c99',deep:'#45727f',sand:'#bbccc0',tree:'#385d57',leaves:'#527e70',highlight:'#91ad99',mountain:'#839d99',title:'Frostbound Reach',sky:'#1c3032'}};
let state,tiles=[],landmarks=[],random,palette,keys=new Set(),lastMove=0,near=null,atlas=false,combat=null,toastTimer,clickTarget=null,audioContext=null,ambientNodes=[],lastSave=0;
const motion={x:40,y:44,fromX:40,fromY:44,cameraX:40,cameraY:44,started:-Infinity,lastFrame:0,walkUntil:0,facing:1};
const reducedMotion=window.matchMedia?.('(prefers-reduced-motion: reduce)');
function animationTime(){return (reducedMotion?.matches||preferences.reduceMotion)?0:performance.now()}
function resetMotion(){Object.assign(motion,{x:state.x,y:state.y,fromX:state.x,fromY:state.y,cameraX:state.x,cameraY:state.y,started:-Infinity,lastFrame:0,walkUntil:0})}
function sampleMotion(now){const progress=(reducedMotion?.matches||preferences.reduceMotion)?1:Math.min(1,Math.max(0,(now-motion.started)/CFG.moveDelay));motion.x=motion.fromX+(state.x-motion.fromX)*progress;motion.y=motion.fromY+(state.y-motion.fromY)*progress}
const cards=[{name:'Melee Strike',symbol:'⚔',desc:'10 damage. A dependable permanent card.',type:'attack'},{name:'Iron Guard',symbol:'◈',desc:'Block the next attack and recover 3 HP.',type:'guard'},{name:'Arcane Bolt',symbol:'ϟ',desc:'17 damage. Costs 5 mana.',type:'magic'},{name:'Second Wind',symbol:'❧',desc:'Restore 20 HP. One use per encounter.',type:'heal'}];
function hash(str){let h=2166136261;for(const c of str){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
function rng(seed){return()=>{seed+=0x6D2B79F5;let t=seed;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}}
function noise(x,y,s){let h=Math.imul(x,374761393)+Math.imul(y,668265263)+s;h=Math.imul(h^(h>>>13),1274126177);return((h^(h>>>16))>>>0)/4294967295}
function smooth(x,y,scale,s){let a=Math.floor(x/scale),b=Math.floor(y/scale),u=x/scale-a,v=y/scale-b;u=u*u*(3-2*u);v=v*v*(3-2*v);return (noise(a,b,s)*(1-u)+noise(a+1,b,s)*u)*(1-v)+(noise(a,b+1,s)*(1-u)+noise(a+1,b+1,s)*u)*v}
const idx=(x,y)=>y*CFG.size+x, distance=(a,b)=>Math.abs(a.x-b.x)+Math.abs(a.y-b.y);
function generate(seed,climate,saved){
 const previousCharacter=state?.character,previousPet=state?.pet,previousHasCharacter=state?.hasCharacter;
 random=rng(hash(seed));palette=PALETTES[climate];tiles=[];landmarks=[];atlas=false;clickTarget=null;combat=null;
 const s=hash(seed);for(let y=0;y<CFG.size;y++)for(let x=0;x<CFG.size;x++){let elevation=smooth(x,y,14,s)*.65+smooth(x,y,6,s+19)*.35;const edge=Math.min(x,y,CFG.size-1-x,CFG.size-1-y);if(edge<4)elevation-=.3*(1-edge/4);let n=noise(x,y,s+37);tiles.push({type:elevation<.31?'water':elevation<.36?'sand':elevation>.76?'mountain':n>.62?'tree':'grass',v:Math.floor(n*4)});}
 const points=[{id:'home',name:'Your Home · Hearthstead',kind:'safe',x:40,y:42,desc:'A little warmth at the edge of the unknown.'},{id:'town',name:'Miller’s Cross',kind:'town',x:19,y:29,desc:'A quiet settlement. A merchant tends the last open stall.'},{id:'ruin1',name:'The Moss Chapel',kind:'ruin',x:55,y:25,relic:'The Verdant Sigil',desc:'Roots embrace a chapel older than the forest. A sentinel guards its altar.'},{id:'ruin2',name:'The Sunken Archive',kind:'ruin',x:20,y:49,relic:'The Tideglass',desc:'Beneath broken stone, the old archive keeps one final secret.'},{id:'ruin3',name:'Emberwatch Tower',kind:'ruin',x:58,y:59,relic:'The Ember Heart',desc:'A forgotten watchtower. A quiet ember still burns at its crown.'},{id:'rift',name:'The Sleeping Gate',kind:'rift',x:42,y:20,desc:'A tear between worlds, waiting for three lost relics.'},{id:'camp',name:'Wayfarer’s Camp',kind:'camp',x:36,y:56,desc:'A campfire and an empty bedroll. Rest awhile.'}];
 for(const p of points){if(p.id!=='home'){p.x+=Math.floor(random()*7)-3;p.y+=Math.floor(random()*7)-3}landmarks.push(p);for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++)tiles[idx(p.x+dx,p.y+dy)]={type:Math.abs(dx)+Math.abs(dy)<3?'clearing':'grass',v:0};}
 // Carve connected trails so every generated landmark remains reachable.
 for(let i=1;i<points.length;i++){const p=points[i],a=points[i===5?1:0];let x=a.x,y=a.y;while(x!==p.x||y!==p.y){if(x!==p.x&&(random()>.45||y===p.y))x+=Math.sign(p.x-x);else y+=Math.sign(p.y-y);tiles[idx(x,y)]={type:'path',v:0};}}
 buildVillage();
 state=saved||{seed,climate,x:40,y:44,hp:CFG.maxHP,mana:20,xp:0,relics:[],cleared:[],seen:[],steps:0,won:false,vaults:1};
 if(!saved&&previousCharacter){state.character=JSON.parse(JSON.stringify(previousCharacter));state.hasCharacter=previousHasCharacter;state.pet=previousPet?{...previousPet}:null}hydrateLife();state.seen=new Set(state.seen);resetMotion();$('worldName').textContent=palette.title;keys.clear();reveal();updateUI();save();notify(saved?'Your journey continues.':'Welcome to Hearthstead. Your entire village is safe.');
}
function reveal(){for(let dy=-CFG.vision;dy<=CFG.vision;dy++)for(let dx=-CFG.vision;dx<=CFG.vision;dx++){let x=state.x+dx,y=state.y+dy;if(x>=0&&y>=0&&x<CFG.size&&y<CFG.size&&dx*dx+dy*dy<CFG.vision**2)state.seen.add(idx(x,y))}}
function save(){try{localStorage.setItem(CFG.saveKey,JSON.stringify({...state,seen:[...state.seen]}));lastSave=Date.now()}catch{notify('Browser storage unavailable — progress lasts for this session only.')}}
function updateUI(){
 $('hpText').textContent=`${state.hp} / ${CFG.maxHP}`;$('hpBar').style.width=state.hp/CFG.maxHP*100+'%';$('level').textContent='LV. '+(1+Math.floor(state.xp/CFG.levelXP));$('cardCount').textContent=(4+state.relics.length+(state.ownedCards?.length||0))+' cards';$('explored').textContent=Math.round(state.seen.size/(CFG.size**2)*100)+'% explored';$('coordinates').textContent=`${CFG.size-state.y}° N · ${state.x}° E`;
 near=landmarks.find(p=>distance(state,p)<=2)||null;$('locationName').textContent=near?near.name:tiles[idx(state.x,state.y)].type==='path'?'The Old Road':'Uncharted Wilds';$('prompt').hidden=!near;$('prompt').querySelector('span').textContent=near?(near.kind==='safe'?'Rest at ':near.kind==='ruin'?'Explore ':'Visit ')+near.name:'';lifeUI();
}
function notify(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500)}
function move(dx,dy){if(lifeMode!=='play'||$('modal').open||atlas)return false;let x=state.x+dx,y=state.y+dy;if(x<1||y<1||x>=CFG.size-1||y>=CFG.size-1)return false;let t=tiles[idx(x,y)].type;if(t==='water'||t==='mountain'||t==='tree')return false;const now=performance.now();sampleMotion(now);motion.fromX=motion.x;motion.fromY=motion.y;motion.started=now;motion.walkUntil=now+CFG.moveDelay;if(dx)motion.facing=dx;state.x=x;state.y=y;state.steps++;reveal();updateUI();if(Date.now()-lastSave>2000)save();afterTravel();return true}
function showModal(html){dismissSpeech();keys.clear();clickTarget=null;$('modalContent').innerHTML=`<button class="close" aria-label="Close dialog">×</button>${html}`;$('modalContent').querySelector('.close').onclick=()=>{if(combat){notify('Finish the encounter or flee to leave.');return}$('modal').close();canvas.focus()};if(!$('modal').open)$('modal').showModal()}
function closeModal(){combat=null;$('modal').close();save();canvas.focus()}
function actionButton(text,id,kind='primary'){return `<button class="${kind}" id="${id}">${text}</button>`}
function interact(){if(lifeMode!=='play'||$('modal').open)return;if(interactLife())return;if(!near)return;const p=near;
 if(p.kind==='safe'||p.kind==='camp'){showModal(`<div class="modal-icon">⌂</div><div class="eyebrow">A MOMENT OF PEACE</div><h2>${p.name}</h2><p>${p.desc} Rest restores your health and mana.</p><div class="actions">${actionButton('Rest by the fire','doRest')}</div>`);$('doRest').onclick=()=>{state.hp=CFG.maxHP;state.mana=maxMana();closeModal();updateUI();notify('The fire restores you. HP and mana replenished.')}}
 else if(p.kind==='town'){showModal(`<div class="modal-icon">⚑</div><div class="eyebrow">SETTLEMENT DISCOVERED</div><h2>${p.name}</h2><p>“The old gate is waking,” the merchant whispers. “Look for the chapel to the northeast, the archive in the west, and Emberwatch in the southeast.”</p><p>Take a rest, traveller. No coin needed today.</p><div class="actions">${actionButton('Rest and resupply','townRest')}</div>`);$('townRest').onclick=()=>{state.hp=CFG.maxHP;state.mana=maxMana();closeModal();updateUI();notify('A warm meal at Miller’s Cross. Supplies restored.')}}
 else if(p.kind==='ruin'){if(state.cleared.includes(p.id)){showModal(`<div class="modal-icon">✧</div><div class="eyebrow">A SECRET REMEMBERED</div><h2>${p.name}</h2><p>You have recovered ${p.relic}. Only silence remains.</p>`);return}showModal(`<div class="modal-icon">♜</div><div class="eyebrow">RELIC SITE DISCOVERED</div><h2>${p.name}</h2><p>${p.desc}</p><p>Defeat its guardian or try to negotiate passage to claim <b>${p.relic}</b>.</p><div class="actions">${actionButton('Approach the guardian →','fight')}${actionButton('Leave quietly','leave','quiet')}</div>`);$('fight').onclick=()=>startCombat(p);$('leave').onclick=closeModal}
 else if(p.kind==='rift'){if(state.relics.length<3){showModal(`<div class="modal-icon">◉</div><div class="eyebrow">THE EDGE OF ANOTHER WORLD</div><h2>The Sleeping Gate</h2><p>Three empty sockets surround the gate. Find the Verdant Sigil, Tideglass, and Ember Heart to open the way.</p><p>${state.relics.length} of 3 relics recovered.</p>`)}else{state.won=true;save();showModal(`<div class="modal-icon">✧</div><div class="eyebrow">CHAPTER I COMPLETE</div><h2>A world beyond.</h2><p>The three relics lift from your hands. The gate opens, and beyond it lies a landscape no one has named.</p><p>You have finished this prototype’s adventure. Step through to generate a new world, or keep exploring this one.</p><div class="actions">${actionButton('Step into a new world →','nextWorld')}${actionButton('Stay a little longer','stay','quiet')}</div>`);$('nextWorld').onclick=()=>{closeModal();generate('REALM-'+Math.floor(Math.random()*999999),state.climate)};$('stay').onclick=closeModal}}
}
function startCombat(place){combat={place,hp:CFG.enemyHP+state.relics.length*8,dice:CFG.dice,healUsed:false,negotiated:false,log:'Choose a card. Spend a die when the moment matters.'};renderCombat()}
function renderCombat(){cards[0].desc=meleeDamage()+' damage. Scales with Might.';const c=combat;const encounterCards=[...cards,...state.ownedCards.map(id=>{const g=GOODS.find(g=>g.id===id);return {name:g.name,symbol:g.icon,desc:g.desc}})];showModal(`<div class="eyebrow">ENCOUNTER · ${c.place.name.toUpperCase()}</div><h2>${c.place.enemy||'The Hollow Sentinel'}</h2><p>${c.place.encounter?'Keep your wits about you. The village is safe; the world beyond has its risks.':'A keeper of forgotten things stands between you and the relic.'}</p><div class="combat-hp"><span>TRAVELLER <b>${state.hp} HP</b> · ${state.mana} mana</span><span>OPPONENT <b>${c.hp} HP</b></span></div><p class="combat-log" role="status">${c.log}</p><label class="dice-label"><input type="checkbox" id="useDie" style="width:auto" ${c.dice===0?'disabled':''}> Augment next card with a die <b>${c.dice} / ${CFG.dice} left</b></label><div class="card-grid">${encounterCards.map((card,i)=>`<button class="play-card" data-card="${i}" ${(i===2&&state.mana<5)||(i===3&&c.healUsed)||(i>=4&&state.mana<GOODS.find(g=>g.id===state.ownedCards[i-4]).mana)?'disabled':''}><span class="symbol">${card.symbol}</span><strong>${card.name}</strong><small>${card.desc}</small></button>`).join('')}</div><div class="actions">${actionButton('Negotiate · one attempt','negotiate','quiet')}${actionButton('Flee to Safe House','flee','quiet')}</div>`);document.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>playCard(Number(b.dataset.card)));$('negotiate').disabled=c.negotiated;$('negotiate').onclick=()=>{c.negotiated=true;if(random()<Math.min(.8,.15+state.character.pillars.influence*.045+state.character.pillars.wit*.035)){victory('Your words reach the sentinel. It steps aside.')}else{c.log='The sentinel refuses. You take 5 damage.';state.hp-=5;finishTurn()}};$('flee').onclick=()=>{closeModal();goHome(false);notify('You escaped to the Safe House. The guardian still waits.')}}
function playCard(i){const c=combat;let bonus=0,rollText='';if($('useDie').checked&&c.dice>0){let roll=Math.min(12,1+Math.floor(random()*12)+Math.floor(state.character.pillars.instinct/3));c.dice--;bonus=roll>=9?8:roll>=4?3:-3;rollText=` Die: ${roll}.`}
 let damage=0,guard=0;if(i===0)damage=Math.max(1,meleeDamage()+bonus);if(i===1){guard=CFG.enemyDamage+4;state.hp=Math.min(CFG.maxHP,state.hp+3+Math.max(0,bonus))}if(i===2){state.mana-=5;damage=13+state.character.pillars.arcane*2+bonus}if(i===3){c.healUsed=true;state.hp=Math.min(CFG.maxHP,state.hp+20+bonus)}if(i>=4){const good=GOODS.find(g=>g.id===state.ownedCards[i-4]);if(!good||state.mana<good.mana)return;state.mana-=good.mana;if(good.damage)damage=good.damage+bonus;else state.hp=Math.min(CFG.maxHP,state.hp+good.healCard+Math.max(0,bonus))}c.hp=Math.max(0,c.hp-damage);if(c.hp===0){victory('The sentinel crumbles. The relic is yours.');return}let incoming=Math.max(0,CFG.enemyDamage+Math.floor(random()*5)-guard);state.hp=Math.max(0,state.hp-incoming);c.log=`${i<4?cards[i].name:GOODS.find(g=>g.id===state.ownedCards[i-4]).name}.${rollText} ${damage?'Dealt '+damage+' damage. ':''}${i===3?'Recovered health. ':''}${incoming?'The sentinel deals '+incoming+' damage.':'You block the sentinel’s attack.'}`;finishTurn()
}
function finishTurn(){updateUI();save();if(state.hp<=0){const protectedByVault=state.vaults>0;if(protectedByVault)state.vaults--;else state.xp=Math.max(0,state.xp-20);combat=null;goHome(true);showModal(`<div class="modal-icon">❧</div><div class="eyebrow">THE HEARTH CALLS YOU BACK</div><h2>${protectedByVault?'Your Vault holds.':'A new beginning.'}</h2><p>${protectedByVault?'Your Vault Card is consumed, protecting your progress.':'You reincarnate at the Safe House, losing up to 20 XP. Your collected relics remain for this experiment.'} Rest, then try another approach.</p><div class="actions">${actionButton('Rise again','rise')}</div>`);$('rise').onclick=closeModal}else renderCombat()}
function victory(message){const p=combat.place;if(p.encounter){state.gold+=12;state.xp+=CFG.combatXP;combat=null;save();updateUI();showModal(`<div class="eyebrow">THE ROAD IS CLEAR · +12 GOLD</div><h2>A little wiser.</h2><p>You survive the encounter. +${CFG.combatXP} XP. The village is always there when you need to rest.</p><div class="actions">${actionButton('Continue travelling','continueTravel')}</div>`);$('continueTravel').onclick=closeModal;return}state.gold+=20;state.relics.push(p.id);state.cleared.push(p.id);state.xp+=CFG.relicXP;state.mana=Math.min(maxMana(),state.mana+5);combat=null;updateUI();save();showModal(`<div class="modal-icon">✧</div><div class="eyebrow">RELIC RECOVERED · +${CFG.relicXP} XP</div><h2>${p.relic}</h2><p>${message}</p><p>${state.relics.length===3?'All three relics are yours. Find the Sleeping Gate to the north.':`${3-state.relics.length} more relic${state.relics.length===1?'s':''} await discovery. Keep following the old roads.`}</p><div class="actions">${actionButton('Continue the journey →','continue')}</div>`);$('continue').onclick=()=>{closeModal();notify(p.relic+' added to your Bustagam.')}}
function goHome(restore){state.x=40;state.y=44;resetMotion();if(restore){state.hp=CFG.maxHP;state.mana=maxMana()}clickTarget=null;reveal();updateUI();save()}
function showBinder(){cards[0].desc=meleeDamage()+' damage. Scales with Might.';showModal(`<div class="eyebrow">THE TRAVELLER’S COLLECTION</div><h2>Your Bustagam</h2><p>Abilities, treasures, and the things worth carrying.</p><div class="pillars">${['Might','Wit','Arcane','Instinct','Influence','Resilience'].map((p,i)=>`<div>${p}<b>${state.character.pillars[PILLAR_INFO[i][0]]}</b></div>`).join('')}</div><div class="card-grid">${cards.map(c=>`<div class="play-card"><span class="symbol">${c.symbol}</span><strong>${c.name}</strong><small>${c.desc}</small></div>`).join('')}${state.ownedCards.map(id=>{const g=GOODS.find(g=>g.id===id);return `<div class="play-card"><span class="symbol">${g.icon}</span><strong>${g.name}</strong><small>${g.desc}</small></div>`}).join('')}${state.relics.map(id=>`<div class="play-card"><span class="symbol">✧</span><strong>${landmarks.find(p=>p.id===id).relic}</strong><small>Quest relic · a key to the Sleeping Gate</small></div>`).join('')}</div><p>${state.vaults} Vault Card · ${state.xp} XP · Your chosen six-pillar attributes.</p>`)}
// Canvas artwork: deterministic terrain, layered trees, landmarks and soft fog.
function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),Math.ceil(w),Math.ceil(h))}
function tree(x,y,t,v){rect(x+t*.44,y+t*.45,t*.13,t*.47,'#473f2e');ctx.fillStyle='#132d232d';ctx.beginPath();ctx.ellipse(x+t*.5,y+t*.83,t*.43,t*.17,0,0,7);ctx.fill();x+=(reducedMotion?.matches||preferences.reduceMotion)?0:Math.sin(animationTime()/1400+v*.7)*1.3;rect(x+t*.15,y+t*.24,t*.7,t*.46,palette.tree);rect(x+t*.24,y+t*.08,t*.5,t*.6,palette.leaves);rect(x+t*.36,y+t*.02,t*.24,t*.26,palette.highlight);rect(x+t*.16,y+t*.35,t*.23,t*.18,palette.leaves);rect(x+t*.62,y+t*.3,t*.2,t*.22,palette.tree)}
